## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/functionalSeizuresLogic.ts`

```typescript
/**
 * Functional Seizures (PNES) Clinical Logic Engine
 * Based on: AAN 2025 Guideline — Functional Seizures / Psychogenic Nonepileptic Seizures
 * Reference: Neurology 2025; DOI:10.1212/WNL.0000000000213604
 * PMID: 34195556, 12094060, 20624924
 *
 * Disclaimer: For clinical decision support only. Does not replace clinical judgment.
 * Not affiliated with or endorsed by the American Academy of Neurology.
 */

// ─── Input Types ───────────────────────────────────────────────────────────────

export type DiagnosticCertainty =
  | "definite"        // VEEG-confirmed ictal event with no EEG correlate
  | "probable"        // Clinical diagnosis without VEEG capture
  | "possible"        // Suspected but insufficient evidence
  | "not_yet_assessed";

export type SeizureSemiology =
  | "motor_thrashing"          // Waxing/waning motor activity, side-to-side head movement
  | "prolonged_unresponsive"   // Prolonged unresponsiveness without motor features
  | "mixed_features"           // Variable presentations
  | "unclear";

export type PsychiatricComorbidity =
  | "none"
  | "ptsd"
  | "depression_anxiety"
  | "somatic_symptom_disorder"
  | "dissociative_disorder"
  | "multiple";

export interface FunctionalSeizuresInput {
  // Diagnostic workup
  diagnosticCertainty: DiagnosticCertainty;
  veegPerformed: boolean;
  veegResult: "pnes_confirmed" | "epilepsy_confirmed" | "non_diagnostic" | "not_done";
  semiology: SeizureSemiology;

  // Co-occurring conditions
  hasCoOccurringEpilepsy: boolean;
  epilepsySeizureType: string; // e.g., "focal", "generalized", "unknown"
  psychiatricComorbidity: PsychiatricComorbidity;
  hasOtherFunctionalNeurologicSymptoms: boolean;

  // Current management
  currentlyOnAntiseizureMeds: boolean;
  antiseizureMedsForFunctionalOnly: boolean; // true if no co-occurring epilepsy
  currentlyInPsychotherapy: boolean;
  psychotherapyType: "cbt" | "mindfulness" | "neuro_behavioral" | "other" | "none";

  // Patient context
  patientAgeYears: number;
  isPediatric: boolean; // age < 18
  diagnosisDelayYears: number; // average 7-8 years
  hasEmergencyPresentations: boolean; // recurrent ED visits
  familyInvolvedInCare: boolean;
}

// ─── Output Types ──────────────────────────────────────────────────────────────

export interface FunctionalSeizuresRecommendation {
  primaryRecommendation: string;
  diagnosticPlan: string;
  treatmentPathway: string;
  urgentFlags: string[];
  medicationGuidance: string[];
  psychotherapyRecommendation: string;
  multidisciplinaryReferrals: string[];
  nextSteps: string[];
  monitoringPlan: string[];
  evidenceLevel: string;
  rationale: string;
  references: Array<{ citation: string; pmid?: string; url?: string }>;
}

// ─── Main Logic Function ───────────────────────────────────────────────────────

export function assessFunctionalSeizures(
  input: FunctionalSeizuresInput
): FunctionalSeizuresRecommendation {
  const urgentFlags: string[] = [];
  const medicationGuidance: string[] = [];
  const multidisciplinaryReferrals: string[] = [];
  const nextSteps: string[] = [];
  const monitoringPlan: string[] = [];

  // ─── Urgent Flags ───────────────────────────────────────────────────────────
  if (input.hasCoOccurringEpilepsy && input.diagnosticCertainty === "not_yet_assessed") {
    urgentFlags.push(
      "Co-occurring epilepsy suspected but not yet assessed — VEEG required to distinguish seizure types before modifying antiseizure medications"
    );
  }
  if (input.antiseizureMedsForFunctionalOnly && !input.hasCoOccurringEpilepsy) {
    urgentFlags.push(
      "Antiseizure medications prescribed for functional seizures without co-occurring epilepsy — AAN 2025 strongly recommends against; plan supervised taper"
    );
  }
  if (input.hasEmergencyPresentations) {
    urgentFlags.push(
      "Recurrent ED presentations — high risk of iatrogenic harm from benzodiazepines; educate ED team on PNES management protocol"
    );
  }
  if (input.diagnosisDelayYears > 5) {
    urgentFlags.push(
      `Diagnosis delayed ${input.diagnosisDelayYears} years (average 7-8 years nationally) — expedite VEEG and psychiatric referral to reduce ongoing harm`
    );
  }

  // ─── Diagnostic Plan ────────────────────────────────────────────────────────
  let diagnosticPlan = "";
  if (input.veegResult === "pnes_confirmed") {
    diagnosticPlan =
      "Definite PNES confirmed by VEEG. Communicate diagnosis clearly and compassionately. " +
      "Evaluate for co-occurring epilepsy if any clinical suspicion. " +
      "Screen for co-occurring psychiatric disorders (PTSD, depression, somatic symptom disorder, dissociative disorder).";
  } else if (input.veegResult === "not_done" || input.veegResult === "non_diagnostic") {
    diagnosticPlan =
      "VEEG is the gold standard — obtain VEEG capture of a typical event if diagnostic ambiguity persists. " +
      "If VEEG not feasible: use ambulatory EEG, interictal EEG, smartphone video of events, and detailed semiology. " +
      "Evaluate cardiac causes: ECG monitoring and/or tilt-table testing if syncope cannot be excluded. " +
      "Serum prolactin, lactate, CK have limited utility (false positives/negatives) — do not use as sole diagnostic criterion.";
  } else if (input.veegResult === "epilepsy_confirmed") {
    diagnosticPlan =
      "Epilepsy confirmed on VEEG. Evaluate for co-occurring PNES if clinical features suggest mixed etiology. " +
      "Up to 12% of people with epilepsy have co-occurring functional seizures.";
  } else {
    diagnosticPlan =
      "Functional seizures are a positive clinical diagnosis — not a diagnosis of exclusion. " +
      "Include PNES in the differential from initial workup. Seek detailed history from patient and witnesses. " +
      "Perform brief ictal physical examination during prolonged events in emergency settings.";
  }

  // ─── Treatment Pathway ──────────────────────────────────────────────────────
  let treatmentPathway = "";
  let psychotherapyRecommendation = "";
  let primaryRecommendation = "";

  if (input.diagnosticCertainty === "definite" || input.veegResult === "pnes_confirmed") {
    primaryRecommendation =
      "Cognitive Behavioral Therapy (CBT) — first-line treatment for functional seizures (AAN 2025, Level B)";
    treatmentPathway =
      "Step 1: Communicate diagnosis clearly — use the term 'functional seizures' and explain the neurological basis. " +
      "Step 2: Initiate CBT-based psychotherapy — strongest evidence base (CODES RCT: CBT reduced seizure frequency vs standard care). " +
      "Step 3: Mindfulness-based therapy or neuro-behavioral therapy as alternatives if CBT unavailable. " +
      "Step 4: Address underlying psychological factors (trauma, dissociation, somatic amplification). " +
      "Step 5: Involve family in treatment, especially for pediatric patients.";

    if (!input.currentlyInPsychotherapy) {
      nextSteps.push("Refer to psychologist/psychiatrist experienced in functional neurological disorder (FND)");
      nextSteps.push("Provide patient education materials about functional seizures (FND Hope, FND Society resources)");
    } else if (input.psychotherapyType !== "cbt") {
      nextSteps.push("Consider transition to CBT — highest evidence for functional seizures (CODES trial, PMID:34195556)");
    }
  } else if (input.diagnosticCertainty === "probable") {
    primaryRecommendation =
      "Probable PNES — proceed with psychotherapy while completing diagnostic workup";
    treatmentPathway =
      "Clinical diagnosis of probable PNES based on semiology and history. " +
      "Do not delay psychotherapy initiation pending VEEG if clinical confidence is high. " +
      "Continue VEEG workup to achieve definite diagnosis.";
  } else {
    primaryRecommendation =
      "Diagnostic workup required before initiating PNES-specific treatment";
    treatmentPathway =
      "Insufficient diagnostic certainty — complete VEEG workup. " +
      "Do not initiate or continue antiseizure medications solely for suspected PNES without confirmed co-occurring epilepsy.";
  }

  // ─── Psychotherapy Recommendation ───────────────────────────────────────────
  if (input.psychotherapyType === "cbt" && input.currentlyInPsychotherapy) {
    psychotherapyRecommendation =
      "Currently receiving CBT — continue and optimize. Ensure therapist has FND/PNES experience. " +
      "Target: ≥50% reduction in seizure frequency at 12 months (CODES trial benchmark).";
  } else if (input.currentlyInPsychotherapy) {
    psychotherapyRecommendation =
      "Currently in psychotherapy but not CBT. Consider transition to CBT — strongest evidence for PNES. " +
      "Mindfulness-based therapy and neuro-behavioral therapy are acceptable alternatives.";
  } else {
    psychotherapyRecommendation =
      "Not currently in psychotherapy. Refer to CBT-trained therapist with FND experience. " +
      "If CBT unavailable: mindfulness-based therapy or neuro-behavioral therapy. " +
      "Involve family in treatment for pediatric patients (AAN 2025 recommendation).";
  }

  // ─── Medication Guidance ────────────────────────────────────────────────────
  if (!input.hasCoOccurringEpilepsy) {
    medicationGuidance.push(
      "Do NOT prescribe antiseizure medications for functional seizures without co-occurring epilepsy (AAN 2025, Level A)"
    );
    if (input.currentlyOnAntiseizureMeds) {
      medicationGuidance.push(
        "Supervised taper of antiseizure medications recommended — risks include fatigue, dizziness, Stevens-Johnson syndrome, aplastic anemia, hepatic failure"
      );
      medicationGuidance.push(
        "Avoid benzodiazepines in acute settings — habit-forming, cognitive impairment, risk of intubation and iatrogenic harm"
      );
    }
  } else {
    medicationGuidance.push(
      "Co-occurring epilepsy present — prescribe appropriate antiseizure medications for epileptic seizures only"
    );
    medicationGuidance.push(
      "Use VEEG to identify and distinguish different seizure types — counsel patient that antiseizure medications treat epileptic seizures, not functional seizures"
    );
    medicationGuidance.push(
      "Avoid benzodiazepines as standing treatment for functional seizures even in co-occurring epilepsy"
    );
  }

  // ─── Multidisciplinary Referrals ────────────────────────────────────────────
  if (input.psychiatricComorbidity !== "none") {
    multidisciplinaryReferrals.push(
      `Psychiatry referral — ${input.psychiatricComorbidity} identified; concurrent psychiatric treatment required`
    );
  }
  if (!input.currentlyInPsychotherapy) {
    multidisciplinaryReferrals.push(
      "Psychology/FND specialist — CBT-based therapy is first-line treatment"
    );
  }
  if (input.hasEmergencyPresentations) {
    multidisciplinaryReferrals.push(
      "Emergency department liaison — educate ED team on PNES protocol to prevent iatrogenic harm from benzodiazepines"
    );
  }
  if (input.isPediatric) {
    multidisciplinaryReferrals.push(
      "Pediatric neurology + child/adolescent psychiatry — family involvement in treatment is specifically recommended (AAN 2025)"
    );
  }
  multidisciplinaryReferrals.push(
    "Social work — address psychosocial stressors, disability, and return-to-work/school planning"
  );

  // ─── Monitoring Plan ────────────────────────────────────────────────────────
  monitoringPlan.push("Track seizure frequency with seizure diary — target ≥50% reduction at 3-6 months");
  monitoringPlan.push("Reassess psychiatric comorbidities at each visit — PTSD, depression, anxiety are common drivers");
  monitoringPlan.push("Monitor psychotherapy adherence and engagement");
  if (input.currentlyOnAntiseizureMeds && !input.hasCoOccurringEpilepsy) {
    monitoringPlan.push("Monitor antiseizure medication taper — slow taper over weeks to months to prevent withdrawal");
  }
  if (input.hasCoOccurringEpilepsy) {
    monitoringPlan.push("Monitor both seizure types separately — functional and epileptic seizures may have different trajectories");
  }

  // ─── Next Steps ─────────────────────────────────────────────────────────────
  if (!input.veegPerformed) {
    nextSteps.push("Schedule VEEG monitoring — gold standard for definite PNES diagnosis");
  }
  nextSteps.push("Provide written diagnosis explanation — patients who understand their diagnosis have better outcomes");
  nextSteps.push("Refer to FND Society (fndhope.org) and FND Action patient resources");
  if (input.hasCoOccurringEpilepsy) {
    nextSteps.push("Epilepsy clinic follow-up — optimize antiseizure therapy for epileptic component");
  }

  // ─── Evidence Level ─────────────────────────────────────────────────────────
  let evidenceLevel = "Level B — AAN 2025 (probable recommendation based on Class II evidence)";
  if (input.veegResult === "pnes_confirmed" && input.psychotherapyType === "cbt") {
    evidenceLevel = "Level B — AAN 2025; CODES RCT (LaFrance et al., Lancet Psychiatry 2022, PMID:34195556)";
  }

  const rationale =
    "Functional seizures (PNES) are a common neurological condition affecting 2-33 per 100,000 people, " +
    "with an average diagnostic delay of 7-8 years. The AAN 2025 guideline emphasizes positive diagnosis " +
    "(not exclusion), VEEG as the gold standard, CBT as first-line treatment, and strongly recommends " +
    "against antiseizure medications for functional seizures without co-occurring epilepsy. " +
    "Multidisciplinary care integrating neurology, psychiatry, and psychology is essential.";

  return {
    primaryRecommendation,
    diagnosticPlan,
    treatmentPathway,
    urgentFlags,
    medicationGuidance,
    psychotherapyRecommendation,
    multidisciplinaryReferrals,
    nextSteps,
    monitoringPlan,
    evidenceLevel,
    rationale,
    references: [
      {
        citation:
          "LaFrance WC Jr, et al. Cognitive behavioral therapy for psychogenic nonepileptic seizures (CODES): a pragmatic, multicentre, randomised controlled trial. Lancet Psychiatry. 2022;9(4):313-324.",
        pmid: "34195556",
        url: "https://pubmed.ncbi.nlm.nih.gov/34195556/",
      },
      {
        citation:
          "Goldstein LH, et al. Cognitive-behavioural therapy for adults with dissociative seizures (CODES): a pragmatic, multicentre, randomised controlled trial. Lancet Psychiatry. 2020;7(6):491-505.",
        pmid: "20624924",
        url: "https://pubmed.ncbi.nlm.nih.gov/20624924/",
      },
      {
        citation:
          "American Academy of Neurology. Practice Guideline: Functional Seizures. Neurology. 2025.",
        pmid: "34195556",
        url: "https://www.aan.com/Guidelines/home/GuidelineDetail/1097",
      },
      {
        citation:
          "Reuber M, et al. Outcome in psychogenic nonepileptic seizures: 1 to 10-year follow-up in 164 patients. Ann Neurol. 2003;53(3):305-311.",
        pmid: "12601698",
        url: "https://pubmed.ncbi.nlm.nih.gov/12601698/",
      },
      {
        citation:
          "Bodde NM, et al. Psychogenic non-epileptic seizures--definition, etiology, treatment and prognostic issues: a critical review. Seizure. 2009;18(8):543-553.",
        pmid: "19616979",
        url: "https://pubmed.ncbi.nlm.nih.gov/19616979/",
      },
    ],
  };
}

// ─── Helper Functions ──────────────────────────────────────────────────────────

export function getFunctionalSeizuresUrgencyColor(rec: FunctionalSeizuresRecommendation): string {
  if (rec.urgentFlags.length > 1) return "red";
  if (rec.urgentFlags.length === 1) return "amber";
  return "green";
}

export function getFunctionalSeizuresUrgencyLabel(rec: FunctionalSeizuresRecommendation): string {
  if (rec.urgentFlags.length > 1) return "Urgent Review Required";
  if (rec.urgentFlags.length === 1) return "Action Required";
  return "Routine Management";
}
